package com.nightclip.app

import android.content.Context
import com.nightclip.core.mobile.Core
import org.json.JSONObject
import java.io.File

/**
 * Process-wide owner of the Go core (docs/architecture.md §2.3). The core is
 * initialised once; the foreground service and the UI both go through here.
 *
 * `com.nightclip.core.mobile.Core` is generated by `make aar`
 * (gomobile bind -javapkg com.nightclip.core ./mobile).
 */
object CoreHost {
    private var core: Core? = null

    @Synchronized
    fun start(context: Context, deviceName: String): Core {
        core?.let { return it }
        val dataDir = File(context.filesDir, "clipbridge").apply { mkdirs() }
        val config = JSONObject()
            .put("data_dir", dataDir.absolutePath)
            .put("device_name", deviceName)
            .put("platform", "android")
            .put("listen", false) // Android only dials out (docs/architecture.md §4.1)
            // TODO(phase0): db_key_b64 comes from an Android Keystore-wrapped secret.
        // gomobile turns Go's NewCore() into the Java constructor Core().
        return Core().also {
            it.init(config.toString())
            core = it
        }
    }

    /** Calls a facade method; returns the parsed reply envelope {"ok":…}. */
    fun call(method: String, params: JSONObject = JSONObject()): JSONObject {
        val c = core ?: error("core not started")
        return JSONObject(c.call(method, params.toString()))
    }

    /** Blocks up to [timeoutMs]; returns null on timeout. Call from a background thread. */
    fun nextEvent(timeoutMs: Int): JSONObject? {
        val c = core ?: return null
        val raw = c.nextEvent(timeoutMs.toLong())
        return if (raw.isEmpty()) null else JSONObject(raw)
    }

    @Synchronized
    fun shutdown() {
        core?.shutdown()
        core = null
    }
}
